import{J as e,n as t,ot as n,q as r}from"./chunks/framework.DStH8c-G.js";var i=JSON.parse(`{"title":"Class: ClientSession","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: ClientSession"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/client/classes/ClientSession"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/client/classes/ClientSession"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/client/src"}},"headers":[],"relativePath":"api/@jsprismarine/client/classes/ClientSession.md","filePath":"api/@jsprismarine/client/classes/ClientSession.md","lastUpdated":1794468377000}`),a={name:`api/@jsprismarine/client/classes/ClientSession.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/client</a> / ClientSession</p><h1 id="class-clientsession" tabindex="-1">Class: ClientSession <a class="header-anchor" href="#class-clientsession" aria-label="Permalink to “Class: ClientSession”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3460940cc602027059cb56fa847cdb2bd16d28d9/packages/client/src/net/ClientSession.ts#L22" target="_blank" rel="noreferrer">client/src/net/ClientSession.ts:22</a></p><p>The Minecraft layer on top of a transport: batching, compression, and turning bytes into decoded packets.</p><p>The counterpart of the server&#39;s <code>MinecraftSession</code>, and it has the same job, but it owns one thing that one does not: the compression state machine. A client sends <code>RequestNetworkSettings</code> and receives <code>NetworkSettings</code> with no algorithm prefix on either, and from the packet after that every batch carries one. Getting that transition wrong does not fail loudly - the first compressed batch is read as if its prefix byte were part of a packet length, and the connection dies several packets later with a decode error that points at the wrong packet entirely.</p><h2 id="extends" tabindex="-1">Extends <a class="header-anchor" href="#extends" aria-label="Permalink to “Extends”">​</a></h2><ul><li><code>EventEmitter</code></li></ul><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new ClientSession</strong>(<code>transport</code>, <code>registry</code>, <code>logger</code>): <code>ClientSession</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3460940cc602027059cb56fa847cdb2bd16d28d9/packages/client/src/net/ClientSession.ts#L50" target="_blank" rel="noreferrer">client/src/net/ClientSession.ts:50</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="transport" tabindex="-1">transport <a class="header-anchor" href="#transport" aria-label="Permalink to “transport”">​</a></h5><p><a href="./../#itransport"><code>ITransport</code></a></p><h5 id="registry" tabindex="-1">registry <a class="header-anchor" href="#registry" aria-label="Permalink to “registry”">​</a></h5><p><a href="./ClientPacketRegistry.html"><code>ClientPacketRegistry</code></a></p><h5 id="logger" tabindex="-1">logger <a class="header-anchor" href="#logger" aria-label="Permalink to “logger”">​</a></h5><p><a href="./../../logger/classes/Logger.html"><code>Logger</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>ClientSession</code></p><h4 id="overrides" tabindex="-1">Overrides <a class="header-anchor" href="#overrides" aria-label="Permalink to “Overrides”">​</a></h4><p><code>EventEmitter.constructor</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="enablecompression" tabindex="-1">enableCompression() <a class="header-anchor" href="#enablecompression" aria-label="Permalink to “enableCompression()”">​</a></h3><blockquote><p><strong>enableCompression</strong>(<code>settings</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3460940cc602027059cb56fa847cdb2bd16d28d9/packages/client/src/net/ClientSession.ts#L67" target="_blank" rel="noreferrer">client/src/net/ClientSession.ts:67</a></p><p>Switches to the negotiated compression, once and in one place.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="settings" tabindex="-1">settings <a class="header-anchor" href="#settings" aria-label="Permalink to “settings”">​</a></h5><p><a href="./../../protocol/#compressionsettings"><code>CompressionSettings</code></a></p><p>what <code>NetworkSettings</code> agreed to.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="enableencryption" tabindex="-1">enableEncryption() <a class="header-anchor" href="#enableencryption" aria-label="Permalink to “enableEncryption()”">​</a></h3><blockquote><p><strong>enableEncryption</strong>(<code>key</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3460940cc602027059cb56fa847cdb2bd16d28d9/packages/client/src/net/ClientSession.ts#L83" target="_blank" rel="noreferrer">client/src/net/ClientSession.ts:83</a></p><p>Switches encryption on, in both directions at once.</p><p>Once and never off, and both directions together: the server enables its own the moment it sends the handshake, so the very next batch either way is encrypted. There is no packet that is sent in the clear after this point, including the <code>ClientToServerHandshake</code> that acknowledges it.</p><p>Not on a transport that encrypts the wire itself: over NetherNet, Bedrock Dedicated Server sends the handshake but keeps batches in the clear under DTLS, and so does this client.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="key" tabindex="-1">key <a class="header-anchor" href="#key" aria-label="Permalink to “key”">​</a></h5><p><code>Buffer</code></p><p>the 32 bytes derived from the shared secret and the server&#39;s salt.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="iscompressionenabled" tabindex="-1">isCompressionEnabled() <a class="header-anchor" href="#iscompressionenabled" aria-label="Permalink to “isCompressionEnabled()”">​</a></h3><blockquote><p><strong>isCompressionEnabled</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3460940cc602027059cb56fa847cdb2bd16d28d9/packages/client/src/net/ClientSession.ts#L92" target="_blank" rel="noreferrer">client/src/net/ClientSession.ts:92</a></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="isencryptionenabled" tabindex="-1">isEncryptionEnabled() <a class="header-anchor" href="#isencryptionenabled" aria-label="Permalink to “isEncryptionEnabled()”">​</a></h3><blockquote><p><strong>isEncryptionEnabled</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3460940cc602027059cb56fa847cdb2bd16d28d9/packages/client/src/net/ClientSession.ts#L88" target="_blank" rel="noreferrer">client/src/net/ClientSession.ts:88</a></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="send" tabindex="-1">send() <a class="header-anchor" href="#send" aria-label="Permalink to “send()”">​</a></h3><blockquote><p><strong>send</strong>(<code>packet</code>, <code>priority?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3460940cc602027059cb56fa847cdb2bd16d28d9/packages/client/src/net/ClientSession.ts#L101" target="_blank" rel="noreferrer">client/src/net/ClientSession.ts:101</a></p><p>Serializes a packet, batches it and hands it to the transport.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="packet" tabindex="-1">packet <a class="header-anchor" href="#packet" aria-label="Permalink to “packet”">​</a></h5><p><a href="./../../protocol/classes/NetworkPacket.html"><code>NetworkPacket</code></a>&lt;<code>any</code>&gt;</p><p>a packet already carrying its data.</p><h5 id="priority" tabindex="-1">priority? <a class="header-anchor" href="#priority" aria-label="Permalink to “priority?”">​</a></h5><p><a href="./../#sendpriority"><code>SendPriority</code></a> = <code>SendPriority.NORMAL</code></p><p>IMMEDIATE for anything the handshake is waiting on.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendimmediate" tabindex="-1">sendImmediate() <a class="header-anchor" href="#sendimmediate" aria-label="Permalink to “sendImmediate()”">​</a></h3><blockquote><p><strong>sendImmediate</strong>(<code>packet</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3460940cc602027059cb56fa847cdb2bd16d28d9/packages/client/src/net/ClientSession.ts#L111" target="_blank" rel="noreferrer">client/src/net/ClientSession.ts:111</a></p><p>The handshake steps, which the server is blocking on and must not be held behind anything.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="packet-1" tabindex="-1">packet <a class="header-anchor" href="#packet-1" aria-label="Permalink to “packet”">​</a></h5><p><a href="./../../protocol/classes/NetworkPacket.html"><code>NetworkPacket</code></a>&lt;<code>any</code>&gt;</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p>`,82)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};